+ * definition of "what is an agent" for discovery AND catalog building.
+ */
+function agentNamesFromFiles(files) {
+  var names = [];
+  for (var i = 0; i < files.length; i++) {
+    if (isAgentConfigFile(files[i])) names.push(toAgentName(files[i]));
+  }
+  return names.sort();
+}
