// Validate workflow YAML + bash-syntax each run block
const fs=require('fs'), cp=require('child_process'), os=require('os'), path=require('path');
let yaml;
try { yaml = require('yaml'); } catch(e) { yaml = null; }
const src = fs.readFileSync('.github/workflows/agent-pack-release.yml','utf8');
if (yaml) { const d = yaml.parse(src); console.log('YAML parse: OK, jobs:', Object.keys(d.jobs).length); }
else { console.log('yaml pkg unavailable — skipping parse'); }
// extract run: blocks (naive block-scalar capture) and bash -n them
const lines = src.split('\n');
let blocks=[], cur=null;
for (let i=0;i<lines.length;i++){
  const m = /^( *)run: \|\s*$/.exec(lines[i]);
  if (m){ cur={indent:m[1].length, body:[]}; continue; }
  if (cur){ if (lines[i].trim()==='' || (lines[i].length - lines[i].replace(/^ */,'').length) > cur.indent){ if(lines[i].trim()!=='') cur.body.push(lines[i].slice(cur.indent+2)); } else { blocks.push(cur); cur=null; } }
}
if (cur) blocks.push(cur);
let ok=0, fail=0;
for (const b of blocks){
  const tmp = path.join(os.tmpdir(),'blk.sh');
  fs.writeFileSync(tmp, b.body.join('\n'));
  try { cp.execSync('bash -n '+tmp); ok++; } catch(e){ fail++; console.log('BASH SYNTAX FAIL:\n'+e.stderr); }
}
console.log('run blocks bash -n:', ok, 'ok /', fail, 'failed');
"

